const materials=new Map();
function mat(c,roughness=.7){const key=c+':'+roughness;if(!materials.has(key))materials.set(key,new T.MeshStandardMaterial({color:c,roughness}));return materials.get(key);}
const geometries={box:new T.BoxGeometry(1,1,1),sphere:new T.SphereGeometry(1,12,8),cylinder:new T.CylinderGeometry(1,1,1,12),cone:new T.ConeGeometry(1,1,7)};
