 const points=c.shape.map(([x,z],i)=>new T.Vector3(x,5+Math.sin(i/c.shape.length*TAU*2)*c.hills,z));this.path=new T.CatmullRomCurve3(points,true,'catmullrom',.42);this.path.arcLengthDivisions=1600;this.path.updateArcLengths();
