 this.clouds=[];for(let i=0;i<14;i++){const g=new T.Group();g.position.set(Math.sin(i*2.4)*360,60+(i%4)*13,Math.cos(i*2.4)*360+90);for(let j=0;j<4;j++){const cloud=mesh('sphere',index===2?0x627491:0xfff5df,g,[j*6,Math.sin(j)*3,0],[9,5,5]);cloud.castShadow=false;}this.root.add(g);this.clouds.push(g);}
 // Start gantry and unmistakable chequered finish line.
 const start=this.frameAt(0),gate=new T.Group();gate.position.copy(start.p);gate.rotation.y=Math.atan2(start.t.x,start.t.z);this.root.add(gate);for(const x of [-11,11]){mesh('cylinder',0xf7e8c6,gate,[x,6.5,0],[.44,13,.44]);mesh('box',0xf47c4b,gate,[x,1,0],[1.3,2,1.3]);}const board=new T.Mesh(new T.PlaneGeometry(22,3.5),new T.MeshBasicMaterial({map:labelTexture('POCKET RALLY'),side:T.DoubleSide}));board.position.set(0,12,0);gate.add(board);for(let x=-9;x<9;x+=1.5)for(let z=-1.5;z<1.5;z+=1.5){mesh('box',(Math.round((x+9)/1.5)+Math.round((z+1.5)/1.5))%2?0x233a44:0xfaf5df,gate,[x+.75,.045,z+.75],[1.5,.025,1.5]).castShadow=false;}
 // Direction chevrons and flags.
 for(let i=0;i<14;i++){let f=this.frameAt((i+.5)/14*this.length,12.5);const g=new T.Group();g.position.copy(f.p);g.rotation.y=Math.atan2(f.t.x,f.t.z)+Math.PI/2;this.root.add(g);mesh('cylinder',0xe6dcbf,g,[0,1.9,0],[.12,3.8,.12]);const sign=new T.Mesh(new T.PlaneGeometry(3.2,1.5),new T.MeshBasicMaterial({map:labelTexture('› ›',index===2?'#81ddd6':'#ffd279','#173642'),side:T.DoubleSide}));sign.position.y=3.6;g.add(sign);}
 this.mergeScenery();
