 this.boostPads=[];for(const s of [.26,.72]){let f=this.frameAt(s*this.length,-3.2),g=new T.Group();g.position.copy(f.p);g.position.y+=.08;g.rotation.y=Math.atan2(f.t.x,f.t.z);this.root.add(g);mesh('box',0xf8b955,g,[0,0,0],[4.5,.05,9]).castShadow=false;for(let z=-3;z<=3;z+=2){const tex=new T.Mesh(new T.PlaneGeometry(3,2),new T.MeshBasicMaterial({map:labelTexture('⌃','#f8b955','#fff7d5',128,128)}));tex.rotation.x=-Math.PI/2;tex.position.set(0,.04,z);g.add(tex);}this.boostPads.push({s:s*this.length,lane:-3.2});}
